//! Cold DSL handlers. Auto-generated by `lyng-dsl-codegen`; selected hot
//! opcodes carry hand-maintained inline SMI fast paths.
//!
//! Each cold opcode has:
//! 1. A `#[unsafe(naked)] extern "C" fn op_xxx_dsl()` emitted by
//!    `llint_handler!`. Pure cold stubs delegate entirely to
//!    `op_xxx_slow_rs` via `call_slow! + dispatch_after_slow!`.
//!    Inline-ported opcodes additionally contain a direct SMI hit path
//!    that bails to `.slow:` on tag-check or overflow.
//! 2. A `extern "C" fn op_xxx_slow_rs(state, ...) -> SlowPathReturn`
//!    shim that reconstructs the args struct from raw u32 operand slots,
//!    calls the semantic body in `crate::vm::semantics::<family>::op_xxx_semantic`,
//!    and translates the outcome back to `SlowPathReturn`.
//! 3. For inline SMI opcodes: the hit path records pending scalar feedback
//!    into the flat `LLInt` feedback sidecar via `record_smi!`; Rust drains
//!    that sidecar at explicit VM run boundaries.
//!
//! Re-run `cargo run -p lyng-dsl-codegen` to regenerate cold stubs after
//! touching `tools/lyng-dsl-codegen/src/main.rs`.

#![allow(
    clippy::cast_possible_truncation,
    clippy::cast_possible_wrap,
    clippy::manual_let_else,
    clippy::not_unsafe_ptr_arg_deref,
    clippy::too_many_lines,
    reason = "DSL cold shims are generated ABI glue: operands arrive as raw u32 slots from LLInt assembly, are narrowed back to manifest-checked bytecode widths, and stay in one opcode-table-shaped file"
)]

#[cfg(target_arch = "aarch64")]
use crate::{
    add_smi_overflow, bit_and_smi, branch, branch_global_cell_generation_mismatch,
    branch_global_cell_mode, branch_if_internal_kind, branch_if_nullish_kind,
    branch_if_object_kind, branch_if_string_or_bigint_kind, branch_named_own_inline_mode,
    branch_named_own_inline_write_mode, branch_named_own_outline_mode,
    branch_named_own_polymorphic_mode, branch_named_proto_inline_mode, branch_nonzero,
    branch_raw_equal_strict_result, branch_value_references_heap, call_rust_probe, call_slow,
    check_object_ref, check_smi, cmp_branch_eq, cmp_branch_ne, dec_smi_overflow, decode_a,
    decode_ab, decode_abc, decode_abc_slot, decode_abx, decode_abx_feedback_slot, decode_ax,
    dispatch, dispatch_after_slow, dispatch_probe_hit_no_refresh, inc_smi_overflow, load_acc,
    load_constant, load_feedback_site, load_global_cell_value_or_branch, load_local_fixed,
    load_named_aux_bits, load_named_handler_bits, load_named_handler_shape,
    load_named_inline_slot_index_or_branch, load_named_inline_writable_slot_index_or_branch,
    load_named_outline_slot_index_or_branch, load_named_target_shape,
    load_object_record_from_state_or_branch, load_outline_slot, load_record_inline_slot,
    load_record_outline_slots_from_state_or_branch, load_record_prototype_or_branch,
    load_record_shape, load_reg, load_state_value, load_uninit_lex_sentinel, mul_smi_overflow,
    record_smi, shift_left_smi, shift_right_smi, store_acc, store_local_fixed,
    store_record_inline_slot, store_record_shape, store_reg, sub_smi_overflow, tag_bool_const,
    tag_null, tag_smi, tag_smi_const, tag_smi_from_signed_byte, tag_undefined,
    tagged_kind_or_branch, untag_object_ref, untag_smi,
};

#[cfg(target_arch = "aarch64")]
use lyng_vm_dsl::llint_handler;

/// Helper namespace for cold-stub shim utilities.
#[cfg(target_arch = "aarch64")]
struct ColdShimHelpers;

#[cfg(target_arch = "aarch64")]
impl ColdShimHelpers {
    /// Read a 2-byte feedback-slot id from `bytes[PC + offset]`.
    /// Slot 0 is the "no feedback" sentinel and returns `None`.
    #[inline]
    fn feedback_slot_from_pc(
        state: &mut crate::dsl::slow_path::LlIntDispatchState<'_, '_>,
        offset: u32,
    ) -> Option<lyng_types::FeedbackSlotId> {
        let inner = state.dispatch_state();
        let pc = inner.pc();
        // SAFETY: `installed.function.instruction_bytes()` is a
        // pub(crate) field reachable through the active frame's
        // installed function (held in `DispatchState.installed`).
        let bytes = inner.installed.function().instruction_bytes();
        let lo = u32::from(bytes.get((pc + offset) as usize).copied()?);
        let hi = u32::from(bytes.get((pc + offset + 1) as usize).copied()?);
        let raw = lo | (hi << 8);
        lyng_types::FeedbackSlotId::from_raw(raw)
    }

    /// Read a `CallRange` (count, base) from `bytes[PC + offset]`.
    /// Layout: bytes 0,1 = count (LE u16); bytes 2,3 = base (LE u16).
    #[inline]
    fn call_range_from_pc(
        state: &mut crate::dsl::slow_path::LlIntDispatchState<'_, '_>,
        offset: u32,
    ) -> lyng_bytecode::CallRange {
        let inner = state.dispatch_state();
        let pc = inner.pc();
        let bytes = inner.installed.function().instruction_bytes();
        let count_lo = bytes.get((pc + offset) as usize).copied().unwrap_or(0);
        let count_hi = bytes.get((pc + offset + 1) as usize).copied().unwrap_or(0);
        let base_lo = bytes.get((pc + offset + 2) as usize).copied().unwrap_or(0);
        let base_hi = bytes.get((pc + offset + 3) as usize).copied().unwrap_or(0);
        let count = u16::from_le_bytes([count_lo, count_hi]);
        let base = u16::from_le_bytes([base_lo, base_hi]);
        lyng_bytecode::CallRange::new(base, count)
    }

    /// Look up `spread_mask` for an optional feedback slot.
    /// Returns `None` when there is no slot or no spread metadata.
    #[inline]
    fn spread_mask_for(
        state: &mut crate::dsl::slow_path::LlIntDispatchState<'_, '_>,
        feedback_slot: Option<lyng_types::FeedbackSlotId>,
    ) -> Option<u64> {
        let slot = feedback_slot?;
        let inner = state.dispatch_state();
        let descriptor = inner.installed.feedback_descriptor_for_slot(slot)?;
        descriptor.metadata().spread_mask()
    }

    /// Look up `spread_mask` from the feedback slot at `bytes[PC + offset]`.
    #[inline]
    fn spread_mask_from_pc(
        state: &mut crate::dsl::slow_path::LlIntDispatchState<'_, '_>,
        offset: u32,
    ) -> Option<u64> {
        let feedback_slot = Self::feedback_slot_from_pc(state, offset);
        Self::spread_mask_for(state, feedback_slot)
    }
}

// =====================================================================
// Nop
// =====================================================================

#[cfg(target_arch = "aarch64")]
llint_handler! {
    op_nop_dsl, opcode_byte = 0, layout = Ax, length = 4, |ax| {
        call_slow!(op_nop_slow_rs, args = [ax]);
        dispatch_after_slow!();
    }
}

#[cfg(target_arch = "aarch64")]
#[allow(unused_variables)]
#[unsafe(no_mangle)]
pub extern "C" fn op_nop_slow_rs(
    state: *mut crate::dsl::llint_state::LlIntState,
    ax: u32,
) -> crate::dsl::slow_path::SlowPathReturn {
    let mut dispatch = unsafe { crate::dsl::slow_path::LlIntDispatchState::from_raw(state) };
    dispatch.sync_from_asm();
    let args = crate::vm::semantics::control_flow::OpNopArgs {
        instruction_len: 4u32,
    };
    let outcome = crate::vm::semantics::control_flow::op_nop_semantic(&mut dispatch, args);
    dispatch.translate_outcome(outcome)
}

