// =====================================================================
// LoadGlobal
// =====================================================================

#[cfg(target_arch = "aarch64")]
llint_handler! {
    op_load_global_dsl, opcode_byte = 14, layout = Abx, length = 6, |a, bx| {
        // Mode-7 GlobalCellLoad fast read: check cached generation,
        // load cell ref inline. The Abx prologue surfaces `a`/`bx` only;
        // the feedback slot id is read from [PC + 4] directly.
        decode_abx_feedback_slot!(t1);
        load_feedback_site!(t1 => t0);
        branch_global_cell_mode!(t0, .slow);
        branch_global_cell_generation_mismatch!(t0, .slow);
        load_global_cell_value_or_branch!(t0 => t2, .slow);
        store_reg!(a, t2);
        dispatch!();
        .slow:
        decode_abx!(a, bx);
        call_slow!(op_load_global_slow_rs, args = [a, bx]);
        dispatch_after_slow!();
    }
}

#[cfg(target_arch = "aarch64")]
#[allow(unused_variables)]
#[unsafe(no_mangle)]
pub extern "C" fn op_load_global_slow_rs(
    state: *mut crate::dsl::llint_state::LlIntState,
    a: u32,
    bx: u32,
) -> crate::dsl::slow_path::SlowPathReturn {
    let mut dispatch = unsafe { crate::dsl::slow_path::LlIntDispatchState::from_raw(state) };
    dispatch.sync_from_asm();
    let args = crate::vm::semantics::names::OpAtomArgs {
        a: a as u16,
        bx,
        instruction_len: 6u32,
        feedback_slot: ColdShimHelpers::feedback_slot_from_pc(&mut dispatch, 4),
    };
    let outcome = crate::vm::semantics::names::op_load_global_semantic(&mut dispatch, args);
    dispatch.translate_outcome(outcome)
}

