// =====================================================================
// LoadThis — inline fast path with sentinel-bail.
//
// Reads the pre-resolved `this` mirror from `LlIntState::frame_this_value`.
// The mirror holds either the real `this` Value or the uninitialized-lexical
// sentinel (`ThisState::Uninitialized` / `ThisState::Lexical`); the sentinel
// bails to slow to handle those arms and refresh the mirror on egress.
// =====================================================================

#[cfg(target_arch = "aarch64")]
llint_handler! {
    op_load_this_dsl, opcode_byte = 28, layout = Abx, length = 4, |a, bx| {
        load_state_value!(10, vm_state_offset = state_this_value);
        load_uninit_lex_sentinel!(11);
        cmp_branch_eq!(10, 11, .slow);
        store_reg!(a, 10);
        dispatch!();
        .slow:
        call_slow!(op_load_this_slow_rs, args = [a, bx]);
        dispatch_after_slow!();
    }
}

