// =====================================================================
// GetNamedProperty
// =====================================================================

#[cfg(target_arch = "aarch64")]
llint_handler! {
    op_get_named_property_dsl, opcode_byte = 77, layout = AbcSlot, length = 6, |a, b, c, slot| {
        load_reg!(b => b);
        check_object_ref!(b, .slow);
        untag_object_ref!(b);
        load_feedback_site!(slot => c);
        branch_named_own_inline_mode!(c, .try_own_outline);
        load_named_handler_bits!(c => slot);
        load_named_inline_slot_index_or_branch!(slot => c, .slow);
        load_object_record_from_state_or_branch!(b => b, .slow);
        load_record_shape!(b => t1);
        load_named_handler_shape!(slot => t2);
        cmp_branch_ne!(t1, t2, .slow);
        load_record_inline_slot!(b, c => t0);
        store_reg!(a, t0);
        dispatch!();
        .try_own_outline:
        branch_named_own_outline_mode!(c, .try_poly);
        load_named_handler_bits!(c => slot);
        load_named_outline_slot_index_or_branch!(slot => c, .slow);
        load_object_record_from_state_or_branch!(b => b, .slow);
        load_record_shape!(b => t1);
        load_named_handler_shape!(slot => t2);
        cmp_branch_ne!(t1, t2, .slow);
        load_record_outline_slots_from_state_or_branch!(b => t2, .slow);
        load_outline_slot!(t2, c => t0);
        store_reg!(a, t0);
        dispatch!();
        .try_poly:
        branch_named_own_polymorphic_mode!(c, .try_proto);
        load_object_record_from_state_or_branch!(b => b, .slow);
        load_record_shape!(b => t1);
        load_named_handler_bits!(c => slot);
        load_named_handler_shape!(slot => t2);
        cmp_branch_ne!(t1, t2, .poly_slot_1);
        load_named_inline_slot_index_or_branch!(slot => c, .slow);
        load_record_inline_slot!(b, c => t0);
        store_reg!(a, t0);
        dispatch!();
        .poly_slot_1:
        load_named_aux_bits!(c => slot);
        load_named_handler_shape!(slot => t2);
        cmp_branch_ne!(t1, t2, .slow);
        load_named_inline_slot_index_or_branch!(slot => c, .slow);
        load_record_inline_slot!(b, c => t0);
        store_reg!(a, t0);
        dispatch!();
        .try_proto:
        branch_named_proto_inline_mode!(c, .slow);
        load_named_handler_bits!(c => slot);
        load_named_aux_bits!(c => t2);
        load_object_record_from_state_or_branch!(b => b, .slow);
        load_record_shape!(b => t1);
        cmp_branch_ne!(t1, t2, .slow);
        load_named_inline_slot_index_or_branch!(slot => c, .slow);
        load_record_prototype_or_branch!(b => b, .slow);
        load_object_record_from_state_or_branch!(b => b, .slow);
        load_record_shape!(b => t1);
        load_named_handler_shape!(slot => t2);
        cmp_branch_ne!(t1, t2, .slow);
        load_record_inline_slot!(b, c => t0);
        store_reg!(a, t0);
        dispatch!();
        .slow:
        decode_abc_slot!(a, b, c, slot);
        call_slow!(op_get_named_property_slow_rs, args = [a, b, c, slot]);
        dispatch_after_slow!();
    }
}

#[cfg(target_arch = "aarch64")]
#[allow(unused_variables)]
#[unsafe(no_mangle)]
pub extern "C" fn op_get_named_property_slow_rs(
    state: *mut crate::dsl::llint_state::LlIntState,
    a: u32,
    b: u32,
    c: u32,
    slot: u32,
) -> crate::dsl::slow_path::SlowPathReturn {
    let mut dispatch = unsafe { crate::dsl::slow_path::LlIntDispatchState::from_raw(state) };
    dispatch.sync_from_asm();
    #[cfg(feature = "diagnostic-counters")]
    record_named_ic_slow_entry(
        &mut dispatch,
        b,
        slot,
        crate::vm::IcSlowPathKind::GetNamedProperty,
    );
    let args = crate::vm::semantics::property::OpPropertyAccessArgs {
        a: a as u16,
        b: b as u16,
        c: c as u16,
        feedback_slot: lyng_types::FeedbackSlotId::from_raw(slot),
        instruction_len: 6u32,
    };
    let outcome =
        crate::vm::semantics::property::op_get_named_property_semantic(&mut dispatch, args);
    dispatch.translate_outcome(outcome)
}

/// Bridge: per-kind, per-cause IC slow-path entry counter bump from a
/// cold-handler shim. Reads the receiver from operand `receiver_register`
/// and bumps the classified counter on `Vm::ic_slow_path_counters`.
/// Centralized so the four named-property slow-path bridges share one
/// path through the `LlIntDispatchState` borrow dance.
#[inline]
#[cfg(all(target_arch = "aarch64", feature = "diagnostic-counters"))]
fn record_named_ic_slow_entry(
    dispatch: &mut crate::dsl::slow_path::LlIntDispatchState<'_, '_>,
    receiver_register: u32,
    slot: u32,
    kind: crate::vm::IcSlowPathKind,
) {
    let inner = dispatch.dispatch_state();
    let view = inner.frame_view();
    let crate::vm::dispatch_state::DispatchState { vm, agent, .. } = &mut *inner;
    vm.record_ic_slow_entry(agent, view, slot, receiver_register as u16, kind);
}

